import React, { useState } from 'react';
import axios from 'axios';
import './LoginPanel.css'; // Import the CSS file

const LoginPanel = () => {
  const [isActive, setIsActive] = useState(false);
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [error, setError] = useState('');

  const handleRegister = () => setIsActive(true);
  const handleLogin = () => setIsActive(false);

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('http://localhost:8000/api/login', {
        email: loginEmail,
        password: loginPassword
      });

      // Laravel backend should return { token: '...', role: 'admin' or 'customer' }
      const { token, role } = response.data;
      localStorage.setItem('token', token);

      if (role === 'admin') {
        window.location.href = '/admin-dashboard';
      } else {
        window.location.href = '/';
      }
    } catch (err) {
      setError('Invalid email or password');
    }
  };

  return (
    <div className="login-panel-wrapper">
      <div className={`container ${isActive ? 'active' : ''}`}>
        <div className="form-container sign-up">
          <form>
            <div className='logo'>
              <span>e</span>Store
            </div>

            <h1>Create Account</h1>
            <div className="social-icons">
              <a href="#" className="icon"><i className="fa-brands fa-google"></i></a>
              <a href="#" className="icon"><i className="fa-brands fa-facebook"></i></a>
              <a href="#" className="icon"><i className="fa-brands fa-instagram"></i></a>
            </div>
            <span>or register with social platforms</span>
            <input type="text" placeholder="Name" />
            <input type="email" placeholder="Email" />
            <input type="password" placeholder="Password" />
            <button>Sign Up</button>
          </form>
        </div>

        <div className="form-container sign-in">
          <form onSubmit={handleLoginSubmit}>
            <div className='logo'>
              <span>e</span>Store
            </div>
            <h1>Log In</h1>
            <div className="social-icons">
              <a href="#" className="icon"><i className="fa-brands fa-google"></i></a>
              <a href="#" className="icon"><i className="fa-brands fa-facebook"></i></a>
              <a href="#" className="icon"><i className="fa-brands fa-instagram"></i></a>
            </div>
            <span>or login with social platforms</span>
            <input
              type="email"
              placeholder="Email"
              value={loginEmail}
              onChange={(e) => setLoginEmail(e.target.value)}
              required
            />
            <input
              type="password"
              placeholder="Password"
              value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              required
            />
            <a href="#">Forget Your Password?</a>
            {error && <p style={{ color: 'red' }}>{error}</p>}
            <button type="submit">Log In</button>
          </form>
        </div>

        <div className="toggle-container">
          <div className="toggle">
            <div className="toggle-panel toggle-left">
              <h1>Welcome Back!</h1>
              <p>Already have Account</p>
              <button className="hidden" onClick={handleLogin}>Log In</button>
            </div>
            <div className="toggle-panel toggle-right">
              <h1>Hello, Welcome!</h1>
              <p>Don't have an Account?</p>
              <button className="hidden" onClick={handleRegister}>Register</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPanel;
